import{_ as a,o as p,c as o,ag as t}from"./chunks/framework.PVHj0As1.js";const r="/pub-blog/assets/image-20260131184115820.B0IeidWM.png",e="/pub-blog/assets/image-20260131184036292.Cyz5wAya.png",s="/pub-blog/assets/image-20260131184546868.FVslWvXm.png",i="/pub-blog/assets/image-20260131185120267.C5kjtKuU.png",l="/pub-blog/assets/image-20260131185526087.SZVi6KFt.png",c="/pub-blog/assets/image-20260131190704557.CPDpZWJj.png",h="/pub-blog/assets/image-20260131190820759.Czr33L-8.png",m="/pub-blog/assets/image-20260131190846956.C_t6r8bE.png",g="/pub-blog/assets/image-20260131190927811.NZIcGts1.png",b="/pub-blog/assets/image-20260131191100026.Ba3ZLWtL.png",u="/pub-blog/assets/image-20260131191503570.CKpeRVw5.png",d="/pub-blog/assets/image-20260131191910452.Qqj96THL.png",_="/pub-blog/assets/image-20260131191955896.haRPtb7T.png",A="/pub-blog/assets/image-20260131192058853.B3aXvK1o.png",y="/pub-blog/assets/image-20260131192130791.DaFGtvek.png",H="/pub-blog/assets/image-20260131192320760.BDBJDKOL.png",k="/pub-blog/assets/image-20260131192444690.BKNaxv0d.png",I="/pub-blog/assets/image-20260131192600565.BfDFqApf.png",f="/pub-blog/assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg",x=JSON.parse('{"title":"AI 时代 人人都可以是开源贡献者（HarmonyOS 开发三方库指南）","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/AI时代-人人都可以是开源贡献者/AI时代-人人都可以是开源贡献者.md","filePath":"鸿蒙开发技巧/AI时代-人人都可以是开源贡献者/AI时代-人人都可以是开源贡献者.md","lastUpdated":1769859061000,"__rawMarkdown":"# AI 时代 人人都可以是开源贡献者（HarmonyOS 开发三方库指南）\\n\\n> 万少：华为HDE、鸿蒙极客\\n>\\n> 个人主页：https://blog.zbztb.cn/\\n>\\n> **2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。**\\n>\\n> 如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。\\n\\n## 前言\\n\\nAI时代的来临，极大的拉近了 **想法 - 过程 - 作品** 的距离，只要你有好的**idea**，**AI**就是你的翅膀，可以极快加速你想法的落地。\\n\\n![](assets/image-20260131184115820.png)\\n\\n> 当然，要是用得过度了，AI也可能可以加速你**身体的负担**~\\n\\n抛弃工作不讲，程序员如何利用好AI来给自身提升价值呢：\\n\\n+ 写博客\\n+ 做产品\\n+ 做技术框架、技术组件\\n\\n我认为以上这些都是可以让AI给我们增加竞争力的。\\n\\n\\n\\n## 示例\\n\\n**这里以一个简单的鸿蒙三方库组件的开发和上架为例**\\n\\n**KeyTone**：是一个可以在鸿蒙应用上，在输入框输入时，增加一点音效的组件。\\n\\n![](assets/image-20260131184036292.png)\\n\\n这个小组件就是一个简单的**想法-作品的体现**\\n\\n## 过程\\n\\n想法就是想要做这样一个小组件，输入框中输入内容，可以播放音效。\\n\\n那么这个过程，我们看看：\\n\\n1. AI制作音频文件\\n\\n2. AI编写组件\\n\\n3. AI编写使用文档\\n\\n4. 提交到GitHub上\\n\\n5. 提交到三方库上\\n\\n   \\n\\n![](assets/image-20260131184546868.png)\\n\\n可以看到，其实最为耗时的过程1、2、3都是AI给我们提效和实现，这个提效和实现不一定是体现在开发速度上，也可能是体现你可以同时用多个AI做多件事情上了。\\n\\n\\n\\n## 技术讲解\\n\\n### 创建Har\\n\\n首先，想要发布到鸿蒙三方库，在已有的工程中需要新建一个静态共享包 **Har**\\n\\n> HAR（Harmony Archive）是静态共享包，可以包含代码、C++库、资源和配置文件。通过HAR可以实现多个模块或多个工程共享ArkUI组件、资源等相关代码。\\n>\\n> - 支持应用内共享，也可以作为二方库（SDK）、三方库（SDK）发布后供其他应用使用。\\n> - 作为二方库（SDK），发布到[OHPM私仓](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/ide-ohpm-repo)，供公司内部其他应用使用。\\n> - 作为三方库（SDK），发布到[OHPM中心仓](https://ohpm.openharmony.cn/#/cn/home)，供其他应用使用。\\n\\n![](assets/image-20260131185120267.png)\\n\\n此时你的工程应该是这样\\n\\n![](assets/image-20260131185526087.png)\\n\\n`entry`作为你正常的一个应用工程\\n\\nkeytone作为你要开发的一个三方库工程\\n\\n那为什么不使用`DevEco Studio` 直接新建一个静态共享包`Har - KeyTone`呢\\n\\n原因是：`entry`属于`Hap`包，它是应用运行的最小单元，\\n\\n也就是你想要实时看到你开发的`Har`包的效果，你的开发必须依托于它。\\n\\n所以一般都是\\n\\n`entry`模块 + 一些 `Har`包类的模块在一个大的工程内。\\n\\n后期发布的时候可以只发布`Har`，也就是`KeyTone`，所以不用担心程序受到污染的问题。\\n\\n\\n\\n### AI编码\\n\\n这个时候是我最轻松的时候，使用自己习惯的AI让它开始按照我的想法开始工作。\\n\\n附上一些对话\\n\\n1. 初始化工程\\n\\n   ![](assets/image-20260131190704557.png)\\n\\n2. 发布需求\\n\\n   ![](assets/image-20260131190820759.png)\\n\\n3. 选择方案\\n\\n   ![](assets/image-20260131190846956.png)\\n\\n   4. 确认计划，开始编码\\n\\n      ![](assets/image-20260131190927811.png)\\n\\n5. 省略中间步骤\\n\\n\\n\\n当然，你的Har包开始开发时，你需要在Entry模块内引入和预览它。\\n\\n这个步骤也可以交给AI。\\n\\n![](assets/image-20260131191100026.png)\\n\\n那这个过程发生了什么事情呢\\n\\nKeyTone中需要导出一些封装好的功能，给开发者调用\\n\\n---\\n\\n\\n\\nEntry模块就可以导入KeyTone模块，然后使用它导出的功能了。\\n\\n![](assets/image-20260131191503570.png)\\n\\n最后运行起来，就可以在模拟器中看到具体效果了。\\n\\n![](assets/image-20260131184036292.png)\\n\\n### 编写Har内的相关信息\\n\\n由于你的Har包后期是需要上传到鸿蒙三方库上给其他开发者使用的。\\n\\n所以你需要填写好对应的一些说明。\\n\\n![](assets/image-20260131191910452.png)\\n\\n具体填写的内容，可以参考文档\\n\\n> 三方库发布的必要文件\\n>\\n> https://ohpm.openharmony.cn/#/cn/help/publishrequirefile\\n>\\n> ![](assets/image-20260131191955896.png)\\n\\n### 构建Har\\n\\n当填写完毕后，需要将KeyTone构建成Har，后期上传到三方库上也是上传Har文件。\\n\\n![](assets/image-20260131192058853.png)\\n\\n---\\n\\n然后在你的`KeyTone`目录内可以得到这个`Har`产物。\\n\\n![image-20260131192130791](assets/image-20260131192130791.png)\\n\\n\\n\\n### 上传Har\\n\\n这个时候，可以使用ohpm功能进行上传这个Har了，想要成功上传，你需要配置一下ohpm和三方库上的环境\\n\\n> 认证管理：https://ohpm.openharmony.cn/#/cn/help/certifymanage\\n>\\n> 发布准备：https://ohpm.openharmony.cn/#/cn/help/createandpublish\\n\\n![](assets/image-20260131192320760.png)\\n\\n\\n\\n一切顺利后，你可以在终端中执行发布命令\\n\\n> ohpm publish 你的Har包地址\\n\\n成功后，在三方库个人中心上可以看到审核信息。\\n\\n![](assets/image-20260131192444690.png)\\n\\n恭喜你，你也是一个开源达人啦！\\n\\n![](assets/image-20260131192600565.png)\\n\\n## 参考文章\\n\\n1. OpenHarmony三方库中心仓\\n\\n   > https://ohpm.openharmony.cn/#/cn/help/introduction\\n\\n2. 应用程序包基础知识\\n\\n   > https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/application-package-fundamentals\\n\\n## 关于我\\n\\n\\n\\n**关注我**，持续分享鸿蒙开发 + AI 提效的实战技巧。\\n\\n![](assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg)\\n\\n"}'),q={name:"鸿蒙开发技巧/AI时代-人人都可以是开源贡献者/AI时代-人人都可以是开源贡献者.md"};function K(E,n,B,P,T,S){return p(),o("div",null,[...n[0]||(n[0]=[t("",76)])])}const v=a(q,[["render",K]]);export{x as __pageData,v as default};
